      <div class="form-row">
        <div class="form-group">
          <label for="nome">{{ 'sections.contatti.form_name' | translate }}</label>
          <input type="text" id="nome" [(ngModel)]="form.nome" name="nome" required [placeholder]="'sections.contatti.form_name' | translate">
